import { test, expect } from '@playwright/test';

test.describe('Checkout Receipt', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com');
    // Assume user is already logged in and has items in the cart
    await page.getByRole('button', { name: /checkout/i }).click();
  });

  test('should display itemised receipt after checkout', async ({ page }) => {
    await page.getByRole('button', { name: /confirm payment/i }).click();
    const receiptTitle = await page.getByText(/receipt/i);
    await expect(receiptTitle).toBeVisible();
  });

  test('should list all purchased items in the receipt', async ({ page }) => {
    await page.getByRole('button', { name: /confirm payment/i }).click();
    const itemList = await page.getByRole('list', { name: /purchased items/i });
    await expect(itemList).toBeVisible();
    const items = await itemList.locator('li');
    await expect(items).toHaveCount(3); // Assuming 3 items were purchased
  });
});
